def compute(vars):
    denominator = vars["v2"]
    if denominator == 0:
        return None

    ratio = vars["v1"] / denominator
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "accrued_interest_and_penalties": vars["v1"],
            "ending_balance": denominator,
            "ratio": ratio,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
